DWORD SendRequest(Http* h,const void* data,UINT bytes){if(h->sent||bytes>h->totalBody)return ERROR_WINHTTP_INCORRECT_HANDLE_STATE;auto e=ConnectRequest(h);if(e)return e;char header[8192]{};UINT at=0;auto append=[&](const char* text){const auto n=Length(text,8192);if(n>sizeof(header)-at-1)return false;Copy(header+at,text,n);at+=n;return true;};if(!append(h->method)||!append(" ")||!append(h->path)||!append(" HTTP/1.1\r\nHost: ")||!append(h->host))return ERROR_INVALID_PARAMETER;if(h->port!=(h->secure?443u:80u)){if(!append(":"))return ERROR_INVALID_PARAMETER;at+=Number(header+at,h->port);}if(!append("\r\nConnection: close\r\nContent-Length: "))return ERROR_INVALID_PARAMETER;at+=Number(header+at,h->totalBody);if(!append("\r\n")||!append(h->extraHeaders)||!append("\r\n"))return ERROR_INVALID_PARAMETER;UINT written=0;e=Write(h,header,at,written);if(e)return e;if(bytes){e=Write(h,data,bytes,written);if(e)return e;}h->sent=true;h->sentBody=bytes;return 0;}
